-- ====================================================================
-- Migration 023: Production Question Bank & Anti-Repeat Architecture
-- Phase 3 Foundation: 1,148-Question Authoritative Master Bank,
-- Synchronized 1v1 Match Question Assignment, 20-Match Sliding-Window
-- Exposure Tracking, Server-Only Answer Security, and MATCHED State Preservation.
--
-- STRICT ISOLATION & COMPATIBILITY NOTICE:
-- 1. Migrations 001-022 remain 100% untouched and preserved.
-- 2. Wallets, Ticket Conversions, Withdrawals, Lifafa Escrow, and PayRupee are 100% untouched.
-- 3. Historical duel_rounds foreign key integrity is preserved (Existing 12 questions remain).
-- 4. Correct answers remain strictly server-only; zero leakage to client views or RPCs.
-- 5. MATCHED -> IN_PROGRESS hotfix is formalized and preserved.
-- ====================================================================

-- 1. Schema Expansion for public.duel_questions
ALTER TABLE public.duel_questions ADD COLUMN IF NOT EXISTS category TEXT;
ALTER TABLE public.duel_questions ADD COLUMN IF NOT EXISTS subcategory TEXT;
ALTER TABLE public.duel_questions ADD COLUMN IF NOT EXISTS pattern_type TEXT;
ALTER TABLE public.duel_questions ADD COLUMN IF NOT EXISTS explanation TEXT;

-- Update existing 12 questions with appropriate metadata
UPDATE public.duel_questions SET
    category = COALESCE(category, 'General'),
    subcategory = COALESCE(subcategory, round_type),
    pattern_type = COALESCE(pattern_type, 'Standard'),
    explanation = COALESCE(explanation, 'Authoritative answer verified by platform engine.')
WHERE category IS NULL;

-- 2. Update Sanitized Public View for Questions
-- Strictly EXCLUDES correct_answer and explanation
DROP VIEW IF EXISTS public.duel_questions_public CASCADE;
CREATE VIEW public.duel_questions_public AS
SELECT
    id,
    round_type,
    prompt,
    options,
    difficulty,
    time_limit_sec,
    category,
    subcategory,
    created_at
FROM public.duel_questions;

REVOKE ALL ON public.duel_questions_public FROM public, anon, authenticated;
GRANT SELECT ON public.duel_questions_public TO authenticated, anon;


-- 3. Add Authoritative Match-Level Question Roster to duel_matches
-- Stores exactly 5 question IDs [q_r1, q_r2, q_r3, q_r4, q_r5] assigned to the match.
-- Both Player A and Player B receive the exact same assigned questions.
ALTER TABLE public.duel_matches ADD COLUMN IF NOT EXISTS round_questions JSONB DEFAULT NULL;


-- 4. Anti-Repeat Question Exposure Ledger Table
-- Tracks question exposures per user to enforce the 20-match sliding-window exclusion.
CREATE TABLE IF NOT EXISTS public.duel_question_exposures (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    question_id TEXT NOT NULL REFERENCES public.duel_questions(id) ON DELETE RESTRICT,
    match_id UUID NOT NULL REFERENCES public.duel_matches(id) ON DELETE CASCADE,
    exposed_at TIMESTAMPTZ NOT NULL DEFAULT TIMEZONE('utc'::text, NOW()),
    CONSTRAINT uq_user_match_question UNIQUE (user_id, match_id, question_id)
);

CREATE INDEX IF NOT EXISTS idx_duel_question_exposures_user_time 
    ON public.duel_question_exposures(user_id, exposed_at DESC);
CREATE INDEX IF NOT EXISTS idx_duel_question_exposures_match 
    ON public.duel_question_exposures(match_id);
CREATE INDEX IF NOT EXISTS idx_duel_question_exposures_q 
    ON public.duel_question_exposures(question_id);

-- Enable RLS on exposure tracking (Users can only inspect their own history)
ALTER TABLE public.duel_question_exposures ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users view own question exposures" ON public.duel_question_exposures;
CREATE POLICY "Users view own question exposures"
    ON public.duel_question_exposures FOR SELECT
    TO authenticated
    USING (user_id = auth.uid());

REVOKE INSERT, UPDATE, DELETE ON public.duel_question_exposures FROM authenticated, anon, public;
GRANT SELECT ON public.duel_question_exposures TO authenticated;


-- 5. Authoritative Match Question Selection Engine (Anti-Repeat Sliding Window)
-- Selects 5 questions (1 per round) excluding questions seen by participating players
-- in their last 20 matches. Includes fallback reservoir sampling if candidate pool is depleted.
CREATE OR REPLACE FUNCTION public.select_duel_match_questions(
    p_user_a UUID,
    p_user_b UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_rounds TEXT[] := ARRAY['QUICK_QUIZ', 'PATTERN', 'MEMORY', 'ACCURACY', 'SPEED'];
    v_round_type TEXT;
    v_selected_ids TEXT[] := ARRAY[]::TEXT[];
    v_qid TEXT;
    v_excluded_ids TEXT[];
BEGIN
    -- Gather questions exposed to player A or player B within their last 20 matches
    WITH recent_matches_a AS (
        SELECT DISTINCT match_id, exposed_at
        FROM public.duel_question_exposures
        WHERE user_id = p_user_a
        ORDER BY exposed_at DESC
        LIMIT 20
    ),
    recent_matches_b AS (
        SELECT DISTINCT match_id, exposed_at
        FROM public.duel_question_exposures
        WHERE p_user_b IS NOT NULL AND user_id = p_user_b
        ORDER BY exposed_at DESC
        LIMIT 20
    ),
    excluded AS (
        SELECT question_id FROM public.duel_question_exposures
        WHERE user_id = p_user_a AND match_id IN (SELECT match_id FROM recent_matches_a)
        UNION
        SELECT question_id FROM public.duel_question_exposures
        WHERE p_user_b IS NOT NULL AND user_id = p_user_b AND match_id IN (SELECT match_id FROM recent_matches_b)
    )
    SELECT ARRAY_AGG(question_id) INTO v_excluded_ids FROM excluded;

    IF v_excluded_ids IS NULL THEN
        v_excluded_ids := ARRAY[]::TEXT[];
    END IF;

    -- Pick 1 authoritative question for each of the 5 battle rounds
    FOREACH v_round_type IN ARRAY v_rounds
    LOOP
        -- Primary attempt: select random question excluding recent exposures
        SELECT id INTO v_qid
        FROM public.duel_questions
        WHERE round_type = v_round_type
          AND NOT (id = ANY(v_excluded_ids))
        ORDER BY random()
        LIMIT 1;

        -- Fallback reservoir: if exhausted, pick any question from round pool
        IF v_qid IS NULL THEN
            SELECT id INTO v_qid
            FROM public.duel_questions
            WHERE round_type = v_round_type
            ORDER BY random()
            LIMIT 1;
        END IF;

        IF v_qid IS NOT NULL THEN
            v_selected_ids := ARRAY_APPEND(v_selected_ids, v_qid);
        END IF;
    END LOOP;

    RETURN to_jsonb(v_selected_ids);
END;
$$;


-- 6. Updated join_matchmaking_rpc
-- Authoritatively selects 5 questions when match is formed, applying the 20-match
-- anti-repeat window for both players, and saves round_questions to duel_matches.
CREATE OR REPLACE FUNCTION public.join_matchmaking_rpc(
    p_display_name TEXT,
    p_avatar_url TEXT DEFAULT NULL,
    p_allow_test_opponent BOOLEAN DEFAULT FALSE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_match RECORD;
    v_new_match_id UUID;
    v_clean_name TEXT;
    v_existing_active_match RECORD;
    v_ticket_balance INTEGER;
    v_player1_id UUID;
    v_round_questions JSONB;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required to join Duel matchmaking';
    END IF;

    v_clean_name := COALESCE(TRIM(p_display_name), 'Challenger');
    IF LENGTH(v_clean_name) = 0 THEN
        v_clean_name := 'Challenger';
    END IF;

    -- Ensure duel_stats row exists for caller
    INSERT INTO public.duel_stats (user_id)
    VALUES (v_user_id)
    ON CONFLICT (user_id) DO NOTHING;

    -- Check if player is already in an active match
    SELECT dm.id, dm.status INTO v_existing_active_match
    FROM public.duel_matches dm
    JOIN public.duel_players dp ON dp.match_id = dm.id
    WHERE dp.player_id = v_user_id
      AND dm.status IN ('MATCHED', 'COUNTDOWN', 'IN_PROGRESS', 'ROUND_TRANSITION')
    ORDER BY dm.created_at DESC
    LIMIT 1;

    IF FOUND THEN
        RETURN jsonb_build_object(
            'success', true,
            'match_id', v_existing_active_match.id,
            'status', v_existing_active_match.status,
            'reconnected', true
        );
    END IF;

    -- Initialize with 0 tickets if new user (no promotional ticket grant)
    INSERT INTO public.game_tickets (user_id, balance)
    VALUES (v_user_id, 0)
    ON CONFLICT (user_id) DO NOTHING;

    SELECT balance INTO v_ticket_balance
    FROM public.game_tickets
    WHERE user_id = v_user_id
    FOR UPDATE;

    IF v_ticket_balance < 1 THEN
        RAISE EXCEPTION 'Insufficient game tickets. 1 ticket required to enter duel.';
    END IF;

    -- Try to find an existing WAITING match with row lock to avoid race conditions
    SELECT dm.* INTO v_match
    FROM public.duel_matches dm
    JOIN public.duel_players dp ON dp.match_id = dm.id
    WHERE dm.status = 'WAITING'
      AND dp.player_id != v_user_id
      AND dm.created_at >= NOW() - INTERVAL '60 seconds'
    ORDER BY dm.created_at ASC
    FOR UPDATE OF dm SKIP LOCKED
    LIMIT 1;

    IF FOUND THEN
        -- Deduct ticket for Player 2
        UPDATE public.game_tickets
        SET balance = balance - 1, updated_at = NOW()
        WHERE user_id = v_user_id;

        INSERT INTO public.game_ticket_transactions (
            user_id, amount, balance_after, transaction_type, reference_id, description
        ) VALUES (
            v_user_id, -1, v_ticket_balance - 1, 'MATCH_ENTRY', v_match.id::text, '1v1 Duel Match Entry'
        );

        -- Find Player 1 ID to calculate combined anti-repeat exclusion
        SELECT player_id INTO v_player1_id
        FROM public.duel_players
        WHERE match_id = v_match.id AND player_slot = 'PLAYER_1'
        LIMIT 1;

        -- Authoritatively select 5 match questions considering both players' recent exposures
        v_round_questions := public.select_duel_match_questions(v_player1_id, v_user_id);

        -- Join as PLAYER_2 and advance status to MATCHED
        INSERT INTO public.duel_players (
            match_id, player_id, player_slot, status, display_name, avatar_url, is_test_opponent
        ) VALUES (
            v_match.id, v_user_id, 'PLAYER_2', 'READY', v_clean_name, p_avatar_url, false
        );

        UPDATE public.duel_matches
        SET status = 'MATCHED',
            round_questions = v_round_questions,
            started_at = NOW(),
            updated_at = NOW()
        WHERE id = v_match.id;

        UPDATE public.duel_players
        SET status = 'READY', updated_at = NOW()
        WHERE match_id = v_match.id AND player_slot = 'PLAYER_1';

        INSERT INTO public.duel_events (match_id, player_id, event_type, payload)
        VALUES (v_match.id, v_user_id, 'PLAYER_JOINED_MATCHED', jsonb_build_object('slot', 'PLAYER_2'));

        RETURN jsonb_build_object(
            'success', true,
            'match_id', v_match.id,
            'player_slot', 'PLAYER_2',
            'status', 'MATCHED',
            'is_test_opponent', false
        );
    END IF;

    -- Test Opponent branch (immediate 1-player match with AI)
    IF p_allow_test_opponent THEN
        UPDATE public.game_tickets
        SET balance = balance - 1, updated_at = NOW()
        WHERE user_id = v_user_id;

        v_round_questions := public.select_duel_match_questions(v_user_id, NULL);

        INSERT INTO public.duel_matches (
            status, current_round, is_test_opponent, round_questions, started_at
        ) VALUES (
            'MATCHED', 1, true, v_round_questions, NOW()
        ) RETURNING id INTO v_new_match_id;

        INSERT INTO public.game_ticket_transactions (
            user_id, amount, balance_after, transaction_type, reference_id, description
        ) VALUES (
            v_user_id, -1, v_ticket_balance - 1, 'MATCH_ENTRY', v_new_match_id::text, '1v1 Duel Test Match Entry'
        );

        INSERT INTO public.duel_players (
            match_id, player_id, player_slot, status, display_name, avatar_url, is_test_opponent
        ) VALUES (
            v_new_match_id, v_user_id, 'PLAYER_1', 'READY', v_clean_name, p_avatar_url, false
        );

        INSERT INTO public.duel_players (
            match_id, player_id, player_slot, status, display_name, avatar_url, is_test_opponent
        ) VALUES (
            v_new_match_id, NULL, 'PLAYER_2', 'READY', 'Vortex (AI)', NULL, true
        );

        INSERT INTO public.duel_events (match_id, player_id, event_type, payload)
        VALUES (v_new_match_id, v_user_id, 'TEST_MATCH_CREATED', jsonb_build_object('slot', 'PLAYER_1'));

        RETURN jsonb_build_object(
            'success', true,
            'match_id', v_new_match_id,
            'player_slot', 'PLAYER_1',
            'status', 'MATCHED',
            'is_test_opponent', true
        );
    END IF;

    -- Normal Matchmaking: Deduct 1 ticket, pre-select questions for Player 1, wait in queue
    UPDATE public.game_tickets
    SET balance = balance - 1, updated_at = NOW()
    WHERE user_id = v_user_id;

    v_round_questions := public.select_duel_match_questions(v_user_id, NULL);

    INSERT INTO public.duel_matches (
        status, current_round, is_test_opponent, round_questions
    ) VALUES (
        'WAITING', 1, false, v_round_questions
    ) RETURNING id INTO v_new_match_id;

    INSERT INTO public.game_ticket_transactions (
        user_id, amount, balance_after, transaction_type, reference_id, description
    ) VALUES (
        v_user_id, -1, v_ticket_balance - 1, 'MATCH_ENTRY', v_new_match_id::text, '1v1 Duel Match Entry'
    );

    INSERT INTO public.duel_players (
        match_id, player_id, player_slot, status, display_name, avatar_url, is_test_opponent
    ) VALUES (
        v_new_match_id, v_user_id, 'PLAYER_1', 'WAITING', v_clean_name, p_avatar_url, false
    );

    INSERT INTO public.duel_events (match_id, player_id, event_type, payload)
    VALUES (v_new_match_id, v_user_id, 'WAITING_IN_QUEUE', jsonb_build_object('slot', 'PLAYER_1'));

    RETURN jsonb_build_object(
        'success', true,
        'match_id', v_new_match_id,
        'player_slot', 'PLAYER_1',
        'status', 'WAITING',
        'is_test_opponent', false
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.join_matchmaking_rpc(TEXT, TEXT, BOOLEAN) TO authenticated;


-- 7. Updated get_duel_round_question_rpc
-- Strictly retrieves the pre-assigned authoritative question from duel_matches.round_questions.
-- Guaranteed identical question for Player A and Player B. Zero answer leakage.
CREATE OR REPLACE FUNCTION public.get_duel_round_question_rpc(
    p_match_id UUID,
    p_round_number INT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_match RECORD;
    v_round_type TEXT;
    v_question_id TEXT;
    v_question RECORD;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    -- Verify match and caller participation
    SELECT * INTO v_match FROM public.duel_matches WHERE id = p_match_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Match not found';
    END IF;

    IF NOT public.check_is_duel_participant(p_match_id) THEN
        RAISE EXCEPTION 'Unauthorized: Caller is not a participant in this match';
    END IF;

    IF p_round_number < 1 OR p_round_number > 5 THEN
        RAISE EXCEPTION 'Invalid round number: %', p_round_number;
    END IF;

    -- Canonical round sequence
    v_round_type := CASE p_round_number
        WHEN 1 THEN 'QUICK_QUIZ'
        WHEN 2 THEN 'PATTERN'
        WHEN 3 THEN 'MEMORY'
        WHEN 4 THEN 'ACCURACY'
        WHEN 5 THEN 'SPEED'
    END;

    -- Retrieve authoritative assigned question ID from match roster
    IF v_match.round_questions IS NOT NULL AND jsonb_array_length(v_match.round_questions) >= p_round_number THEN
        v_question_id := v_match.round_questions->>(p_round_number - 1);
    END IF;

    -- Fetch question details
    IF v_question_id IS NOT NULL THEN
        SELECT id, round_type, prompt, options, difficulty, time_limit_sec, category, subcategory
        INTO v_question
        FROM public.duel_questions
        WHERE id = v_question_id;
    END IF;

    -- Fallback safety (for legacy matches created prior to Migration 023)
    IF v_question.id IS NULL THEN
        SELECT id, round_type, prompt, options, difficulty, time_limit_sec, category, subcategory
        INTO v_question
        FROM public.duel_questions
        WHERE round_type = v_round_type
        LIMIT 1;
    END IF;

    IF v_question.id IS NULL THEN
        RAISE EXCEPTION 'Question unavailable for round %', p_round_number;
    END IF;

    -- Notice: correct_answer and explanation are strictly shielded from client response
    RETURN jsonb_build_object(
        'success', true,
        'round_number', p_round_number,
        'round_type', v_question.round_type,
        'question_id', v_question.id,
        'prompt', v_question.prompt,
        'options', v_question.options,
        'difficulty', v_question.difficulty,
        'time_limit_sec', v_question.time_limit_sec,
        'category', v_question.category,
        'subcategory', v_question.subcategory
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_duel_round_question_rpc(UUID, INT) TO authenticated;


-- 8. Updated submit_round_answer_rpc
-- Preserves MATCHED -> IN_PROGRESS transition, validates submitted question against
-- match roster, scores answer server-side, and records exposure in duel_question_exposures.
CREATE OR REPLACE FUNCTION public.submit_round_answer_rpc(
    p_match_id UUID,
    p_round_number INT,
    p_round_type TEXT,
    p_question_id TEXT,
    p_response TEXT,
    p_response_time_ms INT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_match RECORD;
    v_player RECORD;
    v_question RECORD;
    v_expected_round INT;
    v_is_correct BOOLEAN := false;
    v_score_awarded INTEGER := 0;
    v_speed_bonus INTEGER := 0;
    v_new_total_score INTEGER := 0;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    -- Lock and verify match
    SELECT * INTO v_match
    FROM public.duel_matches
    WHERE id = p_match_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Match % not found', p_match_id;
    END IF;

    -- Formalize & preserve MATCHED alongside active playing states
    IF v_match.status NOT IN ('MATCHED', 'COUNTDOWN', 'IN_PROGRESS', 'ROUND_TRANSITION') THEN
        RAISE EXCEPTION 'Match is not in an active playing state (current status: %)', v_match.status;
    END IF;

    -- Transition MATCHED or COUNTDOWN to IN_PROGRESS upon valid submission
    IF v_match.status IN ('MATCHED', 'COUNTDOWN') THEN
        UPDATE public.duel_matches
        SET status = 'IN_PROGRESS', updated_at = NOW()
        WHERE id = p_match_id;
    END IF;

    -- Verify player is in this match
    SELECT * INTO v_player
    FROM public.duel_players
    WHERE match_id = p_match_id AND player_id = v_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Caller % is not a registered player in match %', v_user_id, p_match_id;
    END IF;

    -- Sequential round enforcement (1 -> 2 -> 3 -> 4 -> 5)
    SELECT COALESCE(MAX(round_number), 0) + 1 INTO v_expected_round
    FROM public.duel_rounds
    WHERE match_id = p_match_id AND player_id = v_user_id;

    IF p_round_number != v_expected_round THEN
        RAISE EXCEPTION 'Round submission out of sequence. Expected round %, received round %', v_expected_round, p_round_number;
    END IF;

    IF p_round_number < 1 OR p_round_number > 5 THEN
        RAISE EXCEPTION 'Invalid round number %. Must be between 1 and 5', p_round_number;
    END IF;

    -- Reject duplicate submission atomically
    IF EXISTS (
        SELECT 1 FROM public.duel_rounds
        WHERE match_id = p_match_id AND round_number = p_round_number AND player_id = v_user_id
    ) THEN
        RAISE EXCEPTION 'Round % already submitted for player %', p_round_number, v_user_id;
    END IF;

    -- Validate question against match roster if available
    IF v_match.round_questions IS NOT NULL AND jsonb_array_length(v_match.round_questions) >= p_round_number THEN
        IF p_question_id != (v_match.round_questions->>(p_round_number - 1)) THEN
            RAISE EXCEPTION 'Submitted question % does not match assigned question for round %', p_question_id, p_round_number;
        END IF;
    END IF;

    -- Server-Authoritative Question Verification against duel_questions table
    SELECT * INTO v_question
    FROM public.duel_questions
    WHERE id = p_question_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Invalid question_id: % does not exist in authoritative question bank', p_question_id;
    END IF;

    IF v_question.round_type != p_round_type THEN
        RAISE EXCEPTION 'Question round type mismatch: question is % but submission claimed %', v_question.round_type, p_round_type;
    END IF;

    -- Validate response_time_ms bounds (reflex threshold >= 50ms)
    IF p_response_time_ms < 50 THEN
        RAISE EXCEPTION 'Response time anomaly: % ms (below human reflex threshold)', p_response_time_ms;
    END IF;

    -- Score calculation with 5000ms timeout grace period
    IF p_response_time_ms > (v_question.time_limit_sec * 1000 + 5000) THEN
        v_is_correct := false;
        v_score_awarded := 0;
    ELSE
        -- Compare answer strictly server-side
        v_is_correct := (TRIM(LOWER(v_question.correct_answer)) = TRIM(LOWER(COALESCE(p_response, ''))));
        IF v_is_correct THEN
            -- Base 100 pts + up to 50 pts speed bonus
            v_speed_bonus := GREATEST(0, LEAST(50, 50 - FLOOR(p_response_time_ms / 500)::INTEGER));
            v_score_awarded := 100 + v_speed_bonus;
        ELSE
            v_score_awarded := 0;
        END IF;
    END IF;

    -- Record round submission
    INSERT INTO public.duel_rounds (
        match_id, round_number, round_type, player_id, question_id,
        player_response, response_time_ms, is_correct, score_awarded
    ) VALUES (
        p_match_id, p_round_number, p_round_type, v_user_id, p_question_id,
        COALESCE(p_response, 'TIMEOUT'), GREATEST(0, p_response_time_ms), v_is_correct, v_score_awarded
    );

    -- Record question exposure for anti-repeat tracking (idempotent)
    INSERT INTO public.duel_question_exposures (
        user_id, question_id, match_id, exposed_at
    ) VALUES (
        v_user_id, p_question_id, p_match_id, NOW()
    ) ON CONFLICT (user_id, match_id, question_id) DO NOTHING;

    -- Update player score atomically
    UPDATE public.duel_players
    SET score = score + v_score_awarded,
        last_heartbeat_at = NOW(),
        updated_at = NOW()
    WHERE match_id = p_match_id AND player_id = v_user_id
    RETURNING score INTO v_new_total_score;

    -- Advance match round if both players completed current round
    IF (
        SELECT COUNT(*) FROM public.duel_rounds
        WHERE match_id = p_match_id AND round_number = p_round_number
    ) = 2 THEN
        IF p_round_number < 5 THEN
            UPDATE public.duel_matches
            SET current_round = p_round_number + 1,
                status = 'ROUND_TRANSITION',
                updated_at = NOW()
            WHERE id = p_match_id;
        END IF;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'round_number', p_round_number,
        'is_correct', v_is_correct,
        'score_awarded', v_score_awarded,
        'total_score', v_new_total_score
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.submit_round_answer_rpc(UUID, INT, TEXT, TEXT, TEXT, INT) TO authenticated;


-- 9. Import Authoritative 1,148-Question Master Bank
-- Non-destructive bulk upsert preserving existing historical question IDs.
INSERT INTO public.duel_questions (
    id, round_type, prompt, options, correct_answer, difficulty, time_limit_sec, category, subcategory, pattern_type, explanation
) VALUES
('q_0001', 'QUICK_QUIZ', 'Which elementary subatomic particle carries a negative fundamental electric charge?', '["Proton", "Neutron", "Electron", "Positron"]'::jsonb, 'Electron', 'EASY', 25, 'Science', 'Physics', 'Direct Factual Recall', 'Electrons orbit atomic nuclei and carry a negative charge of -1e.'),
('q_0002', 'QUICK_QUIZ', 'What optical phenomenon causes white light to split into component colors when traversing a glass prism?', '["Dispersion", "Total Internal Reflection", "Diffraction", "Polarization"]'::jsonb, 'Dispersion', 'MEDIUM', 25, 'Science', 'Optics', 'Concept Identification', 'Dispersion occurs because refractive index varies with the wavelength of light.'),
('q_0003', 'QUICK_QUIZ', 'Which thermodynamic law states that the entropy of an isolated system never decreases over time?', '["Zeroth Law", "First Law", "Second Law", "Third Law"]'::jsonb, 'Second Law', 'EASY', 25, 'Science', 'Thermodynamics', 'Direct Factual Recall', 'The Second Law establishes that natural processes increase the overall entropy of isolated systems.'),
('q_0004', 'QUICK_QUIZ', 'What is the SI derived unit of electrical resistance?', '["Volt", "Ampere", "Ohm", "Siemens"]'::jsonb, 'Ohm', 'EASY', 25, 'Science', 'Electricity', 'Direct Factual Recall', 'The Ohm (symbol: Ω) is defined as 1 volt per ampere.'),
('q_0005', 'QUICK_QUIZ', 'Which color of visible light has the shortest wavelength and highest frequency?', '["Red", "Green", "Blue", "Violet"]'::jsonb, 'Violet', 'EASY', 25, 'Science', 'Optics', 'Comparison', 'Violet light has a wavelength of approximately 380-450 nm, the shortest in the visible spectrum.'),
('q_0006', 'QUICK_QUIZ', 'What physical principle explains why aeroplanes achieve aerodynamic lift over their curved wings?', '["Archimedes Principle", "Bernoulli Principle", "Pascal Law", "Coulomb Law"]'::jsonb, 'Bernoulli Principle', 'MEDIUM', 25, 'Science', 'Fluid Dynamics', 'Concept Identification', 'Bernoulli principle relates higher fluid velocity above the aerofoil with lower pressure relative to the bottom.'),
('q_0007', 'QUICK_QUIZ', 'What is the approximate escape velocity required to leave Earth surface without further propulsion?', '["7.9 km/s", "11.2 km/s", "16.7 km/s", "29.8 km/s"]'::jsonb, '11.2 km/s', 'MEDIUM', 25, 'Science', 'Astrophysics', 'Precision Value', 'Earth surface escape velocity is approximately 11.2 km/s (roughly 40,270 km/h).'),
('q_0008', 'QUICK_QUIZ', 'Which fundamental force binds quarks together inside protons and neutrons?', '["Gravitational force", "Weak nuclear force", "Strong nuclear force", "Electromagnetic force"]'::jsonb, 'Strong nuclear force', 'EASY', 25, 'Science', 'Nuclear Physics', 'Concept Identification', 'The strong force, mediated by gluons, binds quarks together to form nucleons.'),
('q_0009', 'QUICK_QUIZ', 'At what Celsius temperature does liquid water reach its maximum density at 1 atm?', '["0°C", "4°C", "10°C", "100°C"]'::jsonb, '4°C', 'EASY', 25, 'Science', 'Physical Chemistry', 'Direct Factual Recall', 'Pure liquid water has an anomalous density peak at approximately 3.98°C.'),
('q_0010', 'QUICK_QUIZ', 'What type of optical lens is prescribed to correct myopia (nearsightedness)?', '["Convex lens", "Concave lens", "Cylindrical lens", "Bifocal prism"]'::jsonb, 'Concave lens', 'MEDIUM', 25, 'Science', 'Optics', 'Application', 'A diverging concave lens spreads incoming rays so the image focuses directly on the retina.'),
('q_0011', 'QUICK_QUIZ', 'In quantum physics, which constant establishes the direct relation E = hf?', '["Boltzmann constant", "Planck constant", "Avogadro constant", "Rydberg constant"]'::jsonb, 'Planck constant', 'EASY', 25, 'Science', 'Quantum Physics', 'Concept Identification', 'Max Planck introduced h (≈ 6.626 × 10⁻³⁴ J·s) to relate photon energy with electromagnetic frequency.'),
('q_0012', 'QUICK_QUIZ', 'Which metallic chemical element remains in liquid state at standard ambient temperature (25°C)?', '["Gallium", "Mercury", "Bromine", "Cesium"]'::jsonb, 'Mercury', 'MEDIUM', 25, 'Science', 'Chemistry', 'Direct Factual Recall', 'Mercury (Hg) is the only metal that is liquid under standard ambient conditions.'),
('q_0013', 'QUICK_QUIZ', 'What type of radioactive decay emits a helium nucleus consisting of 2 protons and 2 neutrons?', '["Alpha decay", "Beta-minus decay", "Beta-plus decay", "Gamma emission"]'::jsonb, 'Alpha decay', 'EASY', 25, 'Science', 'Nuclear Physics', 'Concept Identification', 'An alpha particle is identical to a helium-4 nucleus (2 protons and 2 neutrons).'),
('q_0014', 'QUICK_QUIZ', 'What is the SI derived unit of magnetic flux density?', '["Weber", "Tesla", "Henry", "Gauss"]'::jsonb, 'Tesla', 'EASY', 25, 'Science', 'Electromagnetism', 'Unit Definition', 'One Tesla equals one Weber per square meter (Wb/m²).'),
('q_0015', 'QUICK_QUIZ', 'Which phenomenon explains the apparent frequency shift of a wave when the source moves relative to an observer?', '["Doppler Effect", "Compton Effect", "Photoelectric Effect", "Cherenkov Radiation"]'::jsonb, 'Doppler Effect', 'MEDIUM', 25, 'Science', 'Acoustics', 'Concept Identification', 'The Doppler effect causes perceived frequency increases when approaching and decreases when receding.'),
('q_0016', 'QUICK_QUIZ', 'Which state of matter consists of a gas of ionized atoms with free electrons at high temperatures?', '["Bose-Einstein Condensate", "Plasma", "Superfluid", "Amorphous Solid"]'::jsonb, 'Plasma', 'MEDIUM', 25, 'Science', 'Physics', 'Concept Identification', 'Plasma is the fourth state of matter, common in lightning, stars, and fusion reactors.'),
('q_0017', 'QUICK_QUIZ', 'According to Einstein Special Theory of Relativity, what happens to the relativistic mass of an object as velocity approaches light speed?', '["Decreases to zero", "Remains strictly constant", "Increases towards infinity", "Fluctuates periodically"]'::jsonb, 'Increases towards infinity', 'HARD', 25, 'Science', 'Relativity', 'Cause and Effect', 'Relativistic mass approaches infinity as speed approaches c, requiring infinite energy to accelerate further.'),
('q_0018', 'QUICK_QUIZ', 'Which electromagnetic radiation possesses wavelengths immediately shorter than visible violet light?', '["Infrared", "Ultraviolet", "X-rays", "Microwaves"]'::jsonb, 'Ultraviolet', 'MEDIUM', 25, 'Science', 'Electromagnetism', 'Sequence / Order', 'Ultraviolet radiation lies between visible violet light and higher-energy X-rays.'),
('q_0019', 'QUICK_QUIZ', 'What property of a fluid measures its internal resistance to flow and shear deformation?', '["Surface tension", "Viscosity", "Buoyancy", "Capillarity"]'::jsonb, 'Viscosity', 'EASY', 25, 'Science', 'Fluid Dynamics', 'Concept Identification', 'Viscosity quantifies internal friction between moving fluid layers.'),
('q_0020', 'QUICK_QUIZ', 'In electrical circuits, what does Kirchhoff Current Law (KCL) state regarding a junction node?', '["Total voltage across a node is zero", "Sum of currents entering equals sum leaving", "Resistance at a node is minimum", "Power dissipated equals current squared"]'::jsonb, 'Sum of currents entering equals sum leaving', 'MEDIUM', 25, 'Science', 'Electrical Circuits', 'Direct Factual Recall', 'KCL is a direct consequence of the conservation of electric charge at any junction.'),
('q_0021', 'QUICK_QUIZ', 'What is the speed of sound in dry air at 20°C approximately?', '["150 m/s", "343 m/s", "767 m/s", "1,500 m/s"]'::jsonb, '343 m/s', 'EASY', 25, 'Science', 'Acoustics', 'Precision Value', 'At 20°C, the speed of sound in dry air is approximately 343 meters per second (1,235 km/h).'),
('q_0022', 'QUICK_QUIZ', 'Which law of planetary motion formulated by Kepler states that planets move in elliptical orbits with the Sun at one focus?', '["First Law", "Second Law", "Third Law", "Universal Gravitation Law"]'::jsonb, 'First Law', 'MEDIUM', 25, 'Space', 'Orbital Mechanics', 'Direct Factual Recall', 'Kepler First Law of Planetary Motion states that planetary orbits are ellipses with the Sun at one focus.'),
('q_0023', 'QUICK_QUIZ', 'What astronomical object forms when a massive star core collapses completely past the neutron degeneracy limit?', '["White dwarf", "Neutron star", "Black hole", "Brown dwarf"]'::jsonb, 'Black hole', 'MEDIUM', 25, 'Space', 'Astrophysics', 'Cause and Effect', 'When core mass exceeds the Tolman-Oppenheimer-Volkoff limit (approx 2-3 solar masses), complete gravitational collapse produces a black hole.'),
('q_0024', 'QUICK_QUIZ', 'Which device stores electrical energy in an electrostatic field between two conductive plates?', '["Inductor", "Resistor", "Capacitor", "Transformer"]'::jsonb, 'Capacitor', 'EASY', 25, 'Science', 'Electronics', 'Concept Identification', 'Capacitors store charge on conductive plates separated by an insulating dielectric material.'),
('q_0025', 'QUICK_QUIZ', 'What is the term for heat transfer occurring through direct molecular collisions without net movement of the material?', '["Convection", "Conduction", "Radiation", "Advection"]'::jsonb, 'Conduction', 'MEDIUM', 25, 'Science', 'Thermodynamics', 'Concept Identification', 'Conduction is thermal energy transfer via intermolecular vibrations in solids and stationary fluids.'),
('q_0026', 'QUICK_QUIZ', 'What is the chemical formula of ozone, the atmospheric molecule that absorbs solar ultraviolet radiation?', '["O2", "O3", "H2O2", "CO2"]'::jsonb, 'O3', 'MEDIUM', 25, 'Science', 'Chemistry', 'Direct Factual Recall', 'Ozone is a triatomic molecule composed of three oxygen atoms (O3).'),
('q_0027', 'QUICK_QUIZ', 'Which element has the highest electrical conductivity of all metals at room temperature?', '["Gold", "Copper", "Silver", "Aluminum"]'::jsonb, 'Silver', 'EASY', 25, 'Science', 'Materials Science', 'Comparison', 'Silver has the highest electrical and thermal conductivity of any known metal.'),
('q_0028', 'QUICK_QUIZ', 'What is the pH value of pure distilled water at 25°C?', '["5.5", "7.0", "8.5", "14.0"]'::jsonb, '7.0', 'EASY', 25, 'Science', 'Chemistry', 'Direct Factual Recall', 'At 25°C, pure water has equal concentrations of H+ and OH- ions, yielding a neutral pH of exactly 7.0.'),
('q_0029', 'QUICK_QUIZ', 'Which gas constitutes approximately 78% of Earth troposphere by volume?', '["Oxygen", "Carbon Dioxide", "Nitrogen", "Argon"]'::jsonb, 'Nitrogen', 'EASY', 25, 'Science', 'Atmospheric Science', 'Direct Factual Recall', 'Dry air is composed of approximately 78.08% nitrogen, 20.95% oxygen, and 0.93% argon.'),
('q_0030', 'QUICK_QUIZ', 'What allotrope of pure carbon consists of a single layer of carbon atoms arranged in a 2D hexagonal lattice?', '["Diamond", "Graphene", "Fullerene", "Lonsdaleite"]'::jsonb, 'Graphene', 'MEDIUM', 25, 'Science', 'Materials Science', 'Concept Identification', 'Graphene is a single atomic monolayer of graphite arranged in a honeycomb sp2-bonded lattice.'),
('q_0031', 'QUICK_QUIZ', 'Which process describes the direct phase transition of a substance from solid to gas without passing through liquid?', '["Evaporation", "Sublimation", "Deposition", "Condensation"]'::jsonb, 'Sublimation', 'MEDIUM', 25, 'Science', 'Chemistry', 'Concept Identification', 'Sublimation occurs when solids like dry ice (solid CO2) transition directly into gaseous state.'),
('q_0032', 'QUICK_QUIZ', 'Which acid is naturally secreted by parietal cells in the human stomach to aid digestion?', '["Sulfuric acid", "Hydrochloric acid", "Nitric acid", "Acetic acid"]'::jsonb, 'Hydrochloric acid', 'EASY', 25, 'Science', 'Biochemistry', 'Direct Factual Recall', 'Gastric parietal cells secrete hydrochloric acid (HCl) maintaining an acidic gastric pH between 1.5 and 3.5.'),
('q_0033', 'QUICK_QUIZ', 'What is the primary chemical component of natural gas used as household and vehicle fuel?', '["Propane", "Butane", "Methane", "Ethane"]'::jsonb, 'Methane', 'EASY', 25, 'Science', 'Chemistry', 'Direct Factual Recall', 'Natural gas is predominantly composed of methane (CH4, typically 70-90%).'),
('q_0034', 'QUICK_QUIZ', 'Which metal is the principal constituent of bronze when alloyed with tin?', '["Iron", "Zinc", "Copper", "Lead"]'::jsonb, 'Copper', 'EASY', 25, 'Science', 'Materials Science', 'Direct Factual Recall', 'Bronze is traditionally an alloy composed of copper (typically 88%) and tin (12%).'),
('q_0035', 'QUICK_QUIZ', 'What chemical process converts vegetable oils into solid fats by adding hydrogen across double bonds?', '["Esterification", "Hydrogenation", "Fermentation", "Saponification"]'::jsonb, 'Hydrogenation', 'MEDIUM', 25, 'Science', 'Organic Chemistry', 'Concept Identification', 'Catalytic hydrogenation saturates carbon-carbon double bonds, raising melting points.'),
('q_0036', 'QUICK_QUIZ', 'Which element has the lowest atomic weight and is the most abundant chemical substance in the universe?', '["Helium", "Hydrogen", "Lithium", "Carbon"]'::jsonb, 'Hydrogen', 'MEDIUM', 25, 'Science', 'Chemistry', 'Direct Factual Recall', 'Hydrogen (H, atomic number 1) accounts for approximately 75% of baryonic mass in the universe.'),
('q_0037', 'QUICK_QUIZ', 'What is the chemical name of common baking soda used in cooking and baking?', '["Sodium carbonate", "Sodium bicarbonate", "Sodium hydroxide", "Calcium carbonate"]'::jsonb, 'Sodium bicarbonate', 'EASY', 25, 'Science', 'Chemistry', 'Direct Factual Recall', 'Baking soda is pure sodium bicarbonate (NaHCO3), which releases CO2 gas when reacting with acids.'),
('q_0038', 'QUICK_QUIZ', 'Which chemical bond forms through the electrostatic attraction between oppositely charged ions?', '["Covalent bond", "Ionic bond", "Metallic bond", "Hydrogen bond"]'::jsonb, 'Ionic bond', 'EASY', 25, 'Science', 'Chemistry', 'Concept Identification', 'Ionic bonds involve electron transfer from a metal to a nonmetal, forming electrostatic lattice attractions.'),
('q_0039', 'QUICK_QUIZ', 'What is the term for a substance that accelerates a chemical reaction without undergoing permanent chemical change itself?', '["Catalyst", "Reagent", "Inhibitor", "Solvent"]'::jsonb, 'Catalyst', 'MEDIUM', 25, 'Science', 'Chemistry', 'Concept Identification', 'A catalyst lowers reaction activation energy without being consumed in the net process.'),
('q_0040', 'QUICK_QUIZ', 'Which radioactive isotope of carbon is universally used in radiocarbon dating of ancient organic materials?', '["Carbon-12", "Carbon-13", "Carbon-14", "Carbon-16"]'::jsonb, 'Carbon-14', 'MEDIUM', 25, 'Science', 'Nuclear Chemistry', 'Direct Factual Recall', 'Carbon-14 has a half-life of approximately 5,730 years and decays into nitrogen-14 via beta decay.'),
('q_0041', 'QUICK_QUIZ', 'Which organelle is universally recognized as the powerhouse of eukaryotic cells due to ATP production?', '["Ribosome", "Golgi apparatus", "Mitochondria", "Endoplasmic reticulum"]'::jsonb, 'Mitochondria', 'MEDIUM', 25, 'Science', 'Cell Biology', 'Concept Identification', 'Mitochondria generate cellular adenosine triphosphate (ATP) through oxidative phosphorylation.'),
('q_0042', 'QUICK_QUIZ', 'What nitrogenous base replaces thymine in single-stranded RNA molecules?', '["Adenine", "Cytosine", "Uracil", "Guanine"]'::jsonb, 'Uracil', 'EASY', 25, 'Science', 'Genetics', 'Direct Factual Recall', 'In ribonucleic acid (RNA), uracil pairs with adenine where thymine would appear in DNA.'),
('q_0043', 'QUICK_QUIZ', 'Which chamber of the human heart pumps oxygenated blood directly into the aorta?', '["Right atrium", "Right ventricle", "Left atrium", "Left ventricle"]'::jsonb, 'Left ventricle', 'EASY', 25, 'Science', 'Anatomy', 'Concept Identification', 'The left ventricle features thick muscular walls to pump oxygenated blood under high pressure through systemic circulation.'),
('q_0044', 'QUICK_QUIZ', 'What type of biological macromolecule are enzymes fundamentally composed of?', '["Carbohydrates", "Proteins", "Lipids", "Nucleic acids"]'::jsonb, 'Proteins', 'EASY', 25, 'Science', 'Biochemistry', 'Concept Identification', 'Almost all biochemical enzymes are globular proteins folded into precise catalytic conformations.'),
('q_0045', 'QUICK_QUIZ', 'Which hormone secreted by the beta cells of the pancreas regulates blood glucose uptake?', '["Glucagon", "Insulin", "Cortisol", "Thyroxine"]'::jsonb, 'Insulin', 'EASY', 25, 'Science', 'Physiology', 'Direct Factual Recall', 'Insulin facilitates cellular absorption of glucose, lowering circulating blood sugar levels.'),
('q_0046', 'QUICK_QUIZ', 'What is the basic functional, structural, and microscopic filtering unit of the human kidney?', '["Nephron", "Neuron", "Alveolus", "Hepatocyte"]'::jsonb, 'Nephron', 'EASY', 25, 'Science', 'Physiology', 'Concept Identification', 'Each human kidney contains approximately one million nephrons that filter blood and form urine.'),
('q_0047', 'QUICK_QUIZ', 'Which pigment in plant chloroplasts is primarily responsible for absorbing sunlight during photosynthesis?', '["Carotenoid", "Anthocyanin", "Chlorophyll", "Xanthophyll"]'::jsonb, 'Chlorophyll', 'MEDIUM', 25, 'Science', 'Botany', 'Direct Factual Recall', 'Chlorophyll a and b absorb blue and red light while reflecting green light, giving plants their green hue.'),
('q_0048', 'QUICK_QUIZ', 'What blood type is universally designated as the universal red blood cell donor in transfusions?', '["A positive", "AB positive", "O negative", "B negative"]'::jsonb, 'O negative', 'EASY', 25, 'Science', 'Medicine', 'Direct Factual Recall', 'O-negative erythrocytes lack A, B, and Rh surface antigens, preventing acute hemolytic transfusion reactions.'),
('q_0049', 'QUICK_QUIZ', 'Which human cranial nerve is primarily responsible for the sensory perception of smell?', '["Optic nerve", "Olfactory nerve", "Trigeminal nerve", "Vagus nerve"]'::jsonb, 'Olfactory nerve', 'EASY', 25, 'Science', 'Neuroscience', 'Direct Factual Recall', 'Cranial Nerve I (the olfactory nerve) transmits sensory olfactory data directly from the nasal epithelium to the brain.'),
('q_0050', 'QUICK_QUIZ', 'What is the term for an organism genetic makeup compared to its observable physical characteristics?', '["Phenotype", "Genotype", "Karyotype", "Haplotype"]'::jsonb, 'Genotype', 'MEDIUM', 25, 'Science', 'Genetics', 'Concept Identification', 'Genotype refers to the specific allelic genetic composition, while phenotype describes the expressed traits.'),
('q_0051', 'QUICK_QUIZ', 'Which specialized connective tissue connects skeletal muscle directly to bone?', '["Ligament", "Tendon", "Cartilage", "Fascia"]'::jsonb, 'Tendon', 'EASY', 25, 'Science', 'Anatomy', 'Direct Factual Recall', 'Tendons connect muscles to bones to transmit force, whereas ligaments connect bone to bone.'),
('q_0052', 'QUICK_QUIZ', 'What is the longest and strongest bone in the human skeleton?', '["Tibia", "Fibula", "Femur", "Humerus"]'::jsonb, 'Femur', 'EASY', 25, 'Science', 'Anatomy', 'Direct Factual Recall', 'The femur (thigh bone) supports body weight during standing, running, and jumping.'),
('q_0053', 'QUICK_QUIZ', 'Which vitamin is synthesized photochemically in human skin upon exposure to solar UVB radiation?', '["Vitamin A", "Vitamin C", "Vitamin D", "Vitamin K"]'::jsonb, 'Vitamin D', 'EASY', 25, 'Science', 'Physiology', 'Direct Factual Recall', 'UVB converts 7-dehydrocholesterol in the epidermis into pre-vitamin D3, subsequently converted into active calcitriol.'),
('q_0054', 'QUICK_QUIZ', 'What is the medical term for the oxygen-carrying metalloprotein found in human red blood cells?', '["Myoglobin", "Hemoglobin", "Albumin", "Ferritin"]'::jsonb, 'Hemoglobin', 'EASY', 25, 'Science', 'Hematology', 'Direct Factual Recall', 'Hemoglobin contains four iron-bearing heme groups that reversibly bind oxygen molecules.'),
('q_0055', 'QUICK_QUIZ', 'Which cellular division process produces four genetically diverse haploid daughter gametes?', '["Mitosis", "Meiosis", "Binary fission", "Budding"]'::jsonb, 'Meiosis', 'EASY', 25, 'Science', 'Genetics', 'Concept Identification', 'Meiosis consists of two successive nuclear divisions reducing chromosomal count by half.'),
('q_0056', 'QUICK_QUIZ', 'What disease is caused by a severe deficiency of Vitamin C in human diet?', '["Rickets", "Beri-beri", "Scurvy", "Pellagra"]'::jsonb, 'Scurvy', 'EASY', 25, 'Science', 'Nutrition', 'Direct Factual Recall', 'Scurvy impairs collagen synthesis, causing bleeding gums, skin spots, and delayed wound healing.'),
('q_0057', 'QUICK_QUIZ', 'Which organ in the human digestive system produces alkaline bile to emulsify dietary lipids?', '["Gallbladder", "Pancreas", "Liver", "Stomach"]'::jsonb, 'Liver', 'EASY', 25, 'Science', 'Anatomy', 'Direct Factual Recall', 'Bile is continuously synthesized by hepatocytes in the liver and stored/concentrated in the gallbladder.'),
('q_0058', 'QUICK_QUIZ', 'What protective membrane encases the human brain and spinal cord in three concentric layers?', '["Pleura", "Pericardium", "Meninges", "Peritoneum"]'::jsonb, 'Meninges', 'EASY', 25, 'Science', 'Anatomy', 'Concept Identification', 'The meninges consist of the dura mater, arachnoid mater, and pia mater.'),
('q_0059', 'QUICK_QUIZ', 'Which group of microorganisms lacks a true membrane-bound nucleus and organelles?', '["Eukaryotes", "Prokaryotes", "Fungi", "Protozoa"]'::jsonb, 'Prokaryotes', 'EASY', 25, 'Science', 'Microbiology', 'Concept Identification', 'Prokaryotes (bacteria and archaea) have uncompartmentalized genetic material lacking a nuclear envelope.'),
('q_0060', 'QUICK_QUIZ', 'What is the term for the symbiotic biological relationship where both participating species derive mutual benefit?', '["Commensalism", "Mutualism", "Parasitism", "Amensalism"]'::jsonb, 'Mutualism', 'MEDIUM', 25, 'Science', 'Ecology', 'Concept Identification', 'Mutualism is an ecological interaction where both species increase their fitness (e.g., bees and flowering plants).'),
('q_0061', 'QUICK_QUIZ', 'What part of the human eye adjusts its curvature to focus light from varying distances onto the retina?', '["Cornea", "Crystalline lens", "Iris", "Pupil"]'::jsonb, 'Crystalline lens', 'MEDIUM', 25, 'Science', 'Anatomy', 'Concept Identification', 'Ciliary muscles contract or relax to alter lens curvature during optical accommodation.'),
('q_0062', 'QUICK_QUIZ', 'Which endocrine gland located at the base of the brain is often referred to as the master gland?', '["Thyroid gland", "Adrenal gland", "Pituitary gland", "Pineal gland"]'::jsonb, 'Pituitary gland', 'EASY', 25, 'Science', 'Endocrinology', 'Direct Factual Recall', 'The pituitary gland secretes tropic hormones that control thyroid, adrenals, and gonads.'),
('q_0063', 'QUICK_QUIZ', 'Which human blood cells are primarily tasked with phagocytosis and immune defense against pathogens?', '["Erythrocytes", "Thrombocytes", "Leukocytes", "Reticulocytes"]'::jsonb, 'Leukocytes', 'MEDIUM', 25, 'Science', 'Immunology', 'Direct Factual Recall', 'Leukocytes (white blood cells) identify, engulf, and destroy invading foreign microbes.'),
('q_0064', 'QUICK_QUIZ', 'What is the genetic condition where an organism has three copies of chromosome 21 instead of two?', '["Turner Syndrome", "Down Syndrome", "Klinefelter Syndrome", "Edwards Syndrome"]'::jsonb, 'Down Syndrome', 'MEDIUM', 25, 'Science', 'Genetics', 'Direct Factual Recall', 'Trisomy 21 is known clinically as Down Syndrome.'),
('q_0065', 'QUICK_QUIZ', 'What specialized cell-cell junction enables rapid electrical impulse transmission in cardiac muscle tissue?', '["Tight junctions", "Gap junctions", "Desmosomes", "Hemidesmosomes"]'::jsonb, 'Gap junctions', 'MEDIUM', 25, 'Science', 'Physiology', 'Concept Identification', 'Intercalated discs contain gap junctions that allow direct ionic current flow between adjacent cardiomyocytes.'),
('q_0066', 'QUICK_QUIZ', 'Which planet in our solar system has the most prominent and extensive planetary ring system visible from Earth?', '["Jupiter", "Saturn", "Uranus", "Neptune"]'::jsonb, 'Saturn', 'MEDIUM', 25, 'Space', 'Planetary Science', 'Direct Factual Recall', 'Saturn has the most extensive planetary ring system composed primarily of water ice and rock particulates.'),
('q_0067', 'QUICK_QUIZ', 'What is the name of the nearest major spiral galaxy to our Milky Way galaxy?', '["Andromeda Galaxy", "Triangulum Galaxy", "Sombrero Galaxy", "Whirlpool Galaxy"]'::jsonb, 'Andromeda Galaxy', 'EASY', 25, 'Space', 'Astronomy', 'Direct Factual Recall', 'The Andromeda Galaxy (M31) is a barred spiral galaxy approximately 2.5 million light-years from Earth.'),
('q_0068', 'QUICK_QUIZ', 'Which celestial body in our solar system possesses the highest volcanic activity and hundreds of active sulfur volcanoes?', '["Europa", "Io", "Titan", "Enceladus"]'::jsonb, 'Io', 'MEDIUM', 25, 'Space', 'Planetary Science', 'Concept Identification', 'Jupiter moon Io is the most volcanically active body in the solar system due to tidal gravitational friction.'),
('q_0069', 'QUICK_QUIZ', 'What is the theoretical boundary region marking the outer gravitational edge of our solar system where comets originate?', '["Kuiper Belt", "Asteroid Belt", "Oort Cloud", "Heliosheath"]'::jsonb, 'Oort Cloud', 'MEDIUM', 25, 'Space', 'Astronomy', 'Concept Identification', 'The Oort cloud is a theoretical spherical cloud of icy planetesimals surrounding the solar system out to 100,000 AU.'),
('q_0070', 'QUICK_QUIZ', 'Which NASA space telescope launched in December 2021 observes the universe primarily in infrared wavelengths from the Sun-Earth L2 Lagrange point?', '["Hubble Space Telescope", "James Webb Space Telescope", "Spitzer Space Telescope", "Kepler Space Telescope"]'::jsonb, 'James Webb Space Telescope', 'HARD', 25, 'Space', 'Space Exploration', 'Direct Factual Recall', 'JWST operates at the Sun-Earth L2 point, utilizing a 6.5-meter beryllium mirror for high-resolution deep infrared imaging.'),
('q_0071', 'QUICK_QUIZ', 'What is the astronomical term for a lunar phase when the Moon passes directly between Earth and the Sun, obscuring the solar disk?', '["Lunar Eclipse", "Solar Eclipse", "Transit of Venus", "Equinox"]'::jsonb, 'Solar Eclipse', 'HARD', 25, 'Space', 'Astronomy', 'Concept Identification', 'A solar eclipse occurs when the Moon occults the Sun, casting a shadow upon Earth.'),
('q_0072', 'QUICK_QUIZ', 'Which planet possesses the longest rotation period, taking approximately 243 Earth days to rotate once and spinning in a retrograde direction?', '["Mercury", "Venus", "Mars", "Uranus"]'::jsonb, 'Venus', 'HARD', 25, 'Space', 'Planetary Science', 'Comparison', 'Venus rotates clockwise (retrograde) once every 243 Earth days, longer than its orbital period of 225 Earth days.'),
('q_0073', 'QUICK_QUIZ', 'What type of stellar remnant is formed when a low-to-intermediate mass star (like our Sun) sheds its outer layers at the end of its life?', '["Neutron star", "White dwarf", "Black hole", "Pulsar"]'::jsonb, 'White dwarf', 'HARD', 25, 'Space', 'Astrophysics', 'Cause and Effect', 'Stars with initial masses under roughly 8 solar masses end their lifecycle as degenerate carbon-oxygen white dwarfs.'),
('q_0074', 'QUICK_QUIZ', 'Which mission executed humanity first successful crewed lunar landing in July 1969?', '["Apollo 8", "Apollo 11", "Apollo 13", "Gemini 4"]'::jsonb, 'Apollo 11', 'EASY', 25, 'Space', 'Space Exploration', 'Direct Factual Recall', 'Apollo 11 landed Neil Armstrong and Buzz Aldrin on the Sea of Tranquility on July 20, 1969.'),
