('q_0820', 'ACCURACY', 'Identify the sentence free of misplaced modifiers:', '["Walking to the store, the rain soaked John.", "Walking to the store, John was soaked by the rain.", "Walking to the store, the rain began to fall on John.", "John, walking to the store, the rain fell."]'::jsonb, 'Walking to the store, John was soaked by the rain.', 'EASY', 20, 'English', 'Grammar', 'Grammatical Accuracy', 'The subject doing the walking ("John") must immediately follow the introductory participial phrase.'),
('q_0821', 'ACCURACY', 'Which sentence demonstrates proper grammatical use of the objective pronoun "whom"?', '["Whom is speaking at the conference tomorrow?", "To whom should this official letter be addressed?", "Whom went to the market?", "Whom made this delicious dessert?"]'::jsonb, 'To whom should this official letter be addressed?', 'MEDIUM', 20, 'English', 'Grammar', 'Grammatical Accuracy', '"Whom" is the objective case pronoun used as the object of preposition "to".'),
