('q_0823', 'ACCURACY', 'Which sentence successfully maintains parallel grammatical structure throughout?', '["She likes hiking, swimming, and to ride bicycles.", "She likes hiking, swimming, and riding bicycles.", "She likes to hike, swimming, and bicycle riding.", "She likes hiking, to swim, and riding."]'::jsonb, 'She likes hiking, swimming, and riding bicycles.', 'MEDIUM', 20, 'English', 'Grammar', 'Grammatical Accuracy', 'Parallelism requires maintaining identical grammatical forms (all gerunds: hiking, swimming, riding).'),
('q_0824', 'ACCURACY', 'Identify the sentence with correct apostrophe usage:', '["The dogs wagged it''s tails.", "The dogs wagged its'' tails.", "The dogs wagged their tails.", "The dog''s wagged their tails."]'::jsonb, 'The dogs wagged their tails.', 'EASY', 20, 'English', 'Grammar', 'Grammatical Accuracy', '"Their" is the correct possessive plural pronoun; "it''s" is the contraction for "it is".'),
('q_0825', 'ACCURACY', 'Which sentence correctly distinguishes "affect" and "effect"?', '["The new policy will have a positive affect on productivity.", "The weather did not effect our travel plans.", "The new policy will have a positive effect on productivity.", "The medicine had an immediate affect."]'::jsonb, 'The new policy will have a positive effect on productivity.', 'EASY', 20, 'English', 'Grammar', 'Grammatical Accuracy', '"Effect" is typically a noun meaning result; "affect" is typically a verb meaning to influence.'),
('q_0826', 'ACCURACY', 'Which sentence correctly links independent clauses using a semicolon?', '["I have a big test tomorrow; therefore, I can''t go to the movie.", "I have a big test tomorrow, therefore; I can''t go to the movie.", "I have a big test tomorrow; and therefore, I can''t go.", "I have a big test tomorrow, therefore, I can''t go;"]'::jsonb, 'I have a big test tomorrow; therefore, I can''t go to the movie.', 'MEDIUM', 20, 'English', 'Grammar', 'Grammatical Accuracy', 'A semicolon joins two independent clauses linked by a conjunctive adverb ("therefore").'),
('q_0827', 'ACCURACY', 'Identify the sentence with correct subject-verb agreement for plural measurements:', '["Ten kilometers are a long distance to walk.", "Ten kilometers is a long distance to walk.", "Ten kilometers have been a long distance.", "Ten kilometers were a long distance."]'::jsonb, 'Ten kilometers is a long distance to walk.', 'MEDIUM', 20, 'English', 'Grammar', 'Grammatical Accuracy', 'Measurements of distance, time, and money viewed as a single quantity take singular verbs ("is").'),
('q_0828', 'ACCURACY', 'Which sentence correctly employs "its" vs "it''s"?', '["The company announced it''s quarterly earnings.", "The cat licked it''s paw.", "It''s raining heavily outside.", "Every country must defend it''s borders."]'::jsonb, 'It''s raining heavily outside.', 'EASY', 20, 'English', 'Grammar', 'Grammatical Accuracy', '"It''s" is the contraction for "It is"; possessive forms use "its".'),
('q_0829', 'ACCURACY', 'Identify the sentence that correctly uses "lay" vs "lie":', '["I am going to lay down on the bed for an hour.", "I am going to lie down on the bed for an hour.", "Yesterday, he laid in bed all morning.", "The book was laying on the table."]'::jsonb, 'I am going to lie down on the bed for an hour.', 'EASY', 20, 'English', 'Grammar', 'Grammatical Accuracy', '"Lie" is intransitive (recline); "lay" is transitive (place something down).'),
('q_0830', 'ACCURACY', 'Identify the sentence with correct verb tense consistency:', '["When the bell rang, the students pack their bags and left.", "When the bell rang, the students packed their bags and left.", "When the bell rings, the students packed their bags.", "When the bell rang, the students are packing."]'::jsonb, 'When the bell rang, the students packed their bags and left.', 'EASY', 20, 'English', 'Grammar', 'Grammatical Accuracy', 'All verbs must consistently remain in past tense: rang, packed, left.'),
('q_0831', 'ACCURACY', 'Which sentence correctly uses "allusion" vs "illusion"?', '["The magician created an optical allusion.", "The poem contains an allusion to Greek mythology.", "Mirages in deserts are optical allusions.", "He was under the allusion that he won."]'::jsonb, 'The poem contains an allusion to Greek mythology.', 'EASY', 20, 'English', 'Grammar', 'Grammatical Accuracy', '"Allusion" means an indirect reference; "illusion" means a deceptive appearance.'),
